/**
 * Internal PKI on a DC (ADR-0007), with the openssl CLI:
 * - root CA (on the DC where it is created; the key stays in /etc/opendc/secrets/pki and can go offline later),
 * - one issuing CA per writable DC; a DC without the root key publishes a CSR that a tier-0 admin approves,
 * - leaf certificates for this node: node (mTLS), web (console), ldaps (Samba), renewed at 2/3 of their life,
 * - revocation in the directory's certificate index and one CRL per issuer, regenerated by its DC.
 * Public data (certificates, CRLs, the index, requests) lives under CN=PKI,CN=OpenDC,CN=System; private keys
 * never leave the host. Every node pins the root it first trusted (trust anchor file), so a certificate swapped
 * in the directory can't become a new anchor.
 */
import { X509Certificate, createPrivateKey, createPublicKey, randomBytes } from 'node:crypto';
import { access, chmod, mkdir, mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { PlatformError } from '@opendc/shared';
import type { OpResult } from '@opendc/shared/agent';
import { childDn, eq, guidToBytes } from '@opendc/shared/ldap';
import {
  LIFETIME_DAYS,
  extensionSection,
  leafSans,
  pkiCert,
  pkiIssuer,
  pkiIssuerRequest,
  pkiRoot,
  renewalDue,
  safeCn,
  serialHex,
  type PkiCert,
  type PkiIssuer,
  type PkiIssuerRequest,
  type PkiRoot,
} from '@opendc/shared/pki';
import { writeSystemFile, type OsActions } from '@opendc/os';
import type { z } from 'zod';
import { addRecord, first, modifyRecord } from './ldif.ts';
import type { SambaLocal } from './local.ts';
import { withGlobalParam } from './smbconf.ts';

const PREFIX = 'opendc:v1:';
const exists = (p: string): Promise<boolean> =>
  access(p).then(
    () => true,
    () => false,
  );
const utc = (d: Date): string => d.toISOString().replace(/[-:T]/g, '').slice(2, 14) + 'Z';

export interface LeafState {
  profile: 'node' | 'web' | 'ldaps';
  serial: string;
  notAfter: string;
  renewed: boolean;
}

/** The public PKI objects in the directory, written through the local sam.ldb (replicated). */
class PkiStore {
  readonly #s: SambaLocal;
  readonly pki: string;
  readonly #who: string;

  constructor(samba: SambaLocal, domainDn: string, who: string) {
    this.#s = samba;
    this.pki = childDn(`CN=OpenDC,CN=System,${domainDn}`, 'CN', 'PKI');
    this.#who = who;
  }

  dn(container: 'Issuers' | 'Certificates' | 'Requests' | null, cn: string): string {
    return container ? childDn(childDn(this.pki, 'CN', container), 'CN', cn) : childDn(this.pki, 'CN', cn);
  }

  async ensureContainers(): Promise<void> {
    for (const dn of [this.pki, ...['Issuers', 'Certificates', 'Requests'].map((c) => childDn(this.pki, 'CN', c))])
      if (!(await this.#s.exists(dn))) await this.#s.add(addRecord(dn, { objectClass: 'container' }));
  }

  async read<S extends z.ZodType>(
    dn: string,
    kind: string,
    schema: S,
  ): Promise<{ data: z.output<S>; rev: number } | null> {
    const raw = first(await this.#s.get(dn, ['msDS-Settings']), 'msDS-Settings');
    if (!raw?.startsWith(PREFIX)) return null;
    try {
      const env = JSON.parse(raw.slice(PREFIX.length)) as { kind?: string; rev?: number; data?: unknown };
      if (env.kind !== kind) return null;
      return { data: schema.parse(env.data), rev: env.rev ?? 1 };
    } catch {
      return null;
    }
  }

  async list<S extends z.ZodType>(
    container: 'Issuers' | 'Certificates' | 'Requests',
    kind: string,
    schema: S,
  ): Promise<z.output<S>[]> {
    const out: z.output<S>[] = [];
    const entries = await this.#s
      .search(childDn(this.pki, 'CN', container), 'one', null, ['msDS-Settings'])
      .catch(() => []);
    for (const e of entries) {
      const r = await this.read(e.dn, kind, schema);
      if (r) out.push(r.data);
    }
    return out;
  }

  async put(dn: string, kind: string, data: unknown, displayName: string): Promise<void> {
    const cur = await this.#s.get(dn, ['msDS-Settings']);
    const raw = first(cur, 'msDS-Settings');
    let rev = 1;
    if (raw?.startsWith(PREFIX)) {
      try {
        rev = ((JSON.parse(raw.slice(PREFIX.length)) as { rev?: number }).rev ?? 0) + 1;
      } catch {
        rev = 1;
      }
    }
    const value =
      PREFIX +
      JSON.stringify({
        schemaVersion: 1,
        kind,
        rev,
        updatedBy: { sid: 'S-1-5-18', name: this.#who, nodeGuid: '' },
        updatedAt: new Date().toISOString(),
        data,
      });
    if (!cur)
      await this.#s.add(addRecord(dn, { objectClass: 'msDS-App-Configuration', displayName, 'msDS-Settings': value }));
    else
      await this.#s.modify(
        modifyRecord(dn, [
          { op: 'replace', attr: 'msDS-Settings', values: [value] },
          { op: 'replace', attr: 'displayName', values: [displayName] },
        ]),
      );
  }
}

/**
 * The CA bundle the API and watcher verify LDAPS with: the OpenDC CAs (root and issuers) when the PKI exists,
 * plus Samba's own CA (DCs whose LDAPS hasn't switched yet). Setup, upgrades and PKI maintenance all use it.
 */
export function ldapCaBundle(opendc: string | null, samba: string | null): string {
  const parts = [opendc, samba].map((x) => x?.trim() ?? '').filter(Boolean);
  return parts.length ? `${parts.join('\n')}\n` : '';
}

export interface PkiPaths {
  /** root-only: keys, the issuer, node and LDAPS certificates */
  keys: string;
  /** public: the pinned root and the CA bundle */
  trust: string;
  consoleKey: string;
  consoleCert: string;
  ldapCa: string;
}

export function pkiPaths(os: OsActions): PkiPaths {
  const p = os.facts.paths;
  return {
    keys: join(p.secrets, 'pki'),
    trust: join(p.etc, 'pki'),
    consoleKey: join(p.secrets, 'tls-key.pem'),
    consoleCert: join(p.secrets, 'tls-cert.pem'),
    ldapCa: join(p.secrets, 'ldap-ca.pem'),
  };
}

/** Every PKI operation of this agent runs after the previous one (the watcher and an admin may overlap). */
let queue: Promise<unknown> = Promise.resolve();
function queued<T>(fn: () => Promise<T>): Promise<T> {
  const run = queue.then(fn, fn);
  queue = run.catch(() => undefined);
  return run;
}

export class Pki {
  readonly #os: OsActions;
  readonly #samba: SambaLocal;
  readonly #p: PkiPaths;
  readonly #now: () => Date;
  #info: { host: string; fqdn: string; nodeGuid: string; domainDn: string; domain: string } | null = null;
  #store: PkiStore | null = null;

  constructor(os: OsActions, samba: SambaLocal, o: { paths?: PkiPaths; now?: () => Date } = {}) {
    this.#os = os;
    this.#samba = samba;
    this.#p = o.paths ?? pkiPaths(os);
    this.#now = o.now ?? (() => new Date());
  }

  // ---------------------------------------------------------------- basics

  async #node() {
    if (this.#info) return this.#info;
    const sys = await this.#os.system.info();
    const host = (sys.hostname.split('.')[0] ?? '').toLowerCase();
    const domainDn = await this.#samba.domainDn();
    const [me] = await this.#samba.search(domainDn, 'sub', eq('sAMAccountName', `${host.toUpperCase()}$`), [
      'objectGUID',
    ]);
    const nodeGuid = (first(me, 'objectGUID') ?? '').toLowerCase();
    if (!nodeGuid) throw new PlatformError('request.not-found', { what: `Computer account ${host}$` });
    const domain = domainDn
      .split(',')
      .map((x) => x.slice(3))
      .join('.')
      .toLowerCase();
    this.#info = { host, fqdn: sys.fqdn.toLowerCase(), nodeGuid, domainDn, domain };
    return this.#info;
  }

  async #db(): Promise<PkiStore> {
    if (this.#store) return this.#store;
    const n = await this.#node();
    this.#store = new PkiStore(this.#samba, n.domainDn, `opendc-agent@${n.host}`);
    await this.#store.ensureContainers();
    return this.#store;
  }

  async #ssl(argv: string[]): Promise<string> {
    const bin = await this.#os.facts.binaries.resolve('openssl');
    return (await this.#os.exec(bin, argv, { timeoutMs: 60_000 })).stdout;
  }

  async #tmp<T>(fn: (dir: string) => Promise<T>): Promise<T> {
    await mkdir(this.#p.keys, { recursive: true, mode: 0o700 });
    const dir = await mkdtemp(join(this.#p.keys, 'tmp-'));
    try {
      return await fn(dir);
    } finally {
      await rm(dir, { recursive: true, force: true });
    }
  }

  async #newKey(path: string): Promise<void> {
    await this.#ssl(['genpkey', '-algorithm', 'EC', '-pkeyopt', 'ec_paramgen_curve:P-256', '-out', path]);
    await chmod(path, 0o600);
  }

  /** Signs `csrPem` with the given CA (or self-signs with `selfKey`); returns the certificate PEM. */
  async #sign(o: {
    csrPem: string;
    ca: { cert: string; key: string } | { selfKey: string };
    days: number;
    ext: string;
  }): Promise<string> {
    return this.#tmp(async (dir) => {
      const csr = join(dir, 'req.csr');
      const ext = join(dir, 'ext.cnf');
      const out = join(dir, 'cert.pem');
      await writeFile(csr, o.csrPem, { mode: 0o600 });
      await writeFile(ext, o.ext, { mode: 0o600 });
      const signer = 'selfKey' in o.ca ? ['-signkey', o.ca.selfKey] : ['-CA', o.ca.cert, '-CAkey', o.ca.key];
      await this.#ssl([
        'x509',
        '-req',
        '-in',
        csr,
        ...signer,
        '-set_serial',
        `0x${serialHex(randomBytes(16))}`,
        '-days',
        String(o.days),
        '-sha256',
        '-extfile',
        ext,
        '-extensions',
        'v3',
        '-out',
        out,
      ]);
      return readFile(out, 'utf8');
    });
  }

  async #csr(keyPath: string, cn: string): Promise<string> {
    return this.#tmp(async (dir) => {
      const out = join(dir, 'req.csr');
      await this.#ssl(['req', '-new', '-key', keyPath, '-subj', `/CN=${safeCn(cn)}/O=OpenDC`, '-out', out]);
      return readFile(out, 'utf8');
    });
  }

  #file = (name: string): string => join(this.#p.keys, name);

  async #keyMatches(keyPath: string, cert: X509Certificate): Promise<boolean> {
    try {
      const pub = createPublicKey(createPrivateKey(await readFile(keyPath, 'utf8')));
      return pub.export({ type: 'spki', format: 'pem' }) === cert.publicKey.export({ type: 'spki', format: 'pem' });
    } catch {
      return false;
    }
  }
  #issuerId = (host: string): string => `issuer-${host}`;

  async #readCert(path: string): Promise<X509Certificate | null> {
    const t = await readFile(path, 'utf8').catch(() => null);
    if (!t) return null;
    try {
      return new X509Certificate(t);
    } catch {
      return null;
    }
  }

  // ---------------------------------------------------------------- root and issuers

  /**
   * Creates the root CA on this DC (once per domain), its issuing CA and this node's certificates. When the domain
   * already has a root (setup resumed, or another DC created it), it only runs the maintenance.
   */
  initRoot(): Promise<OpResult<'ca.init'>> {
    return queued(() => this.#initRoot());
  }

  async #initRoot(): Promise<OpResult<'ca.init'>> {
    const n = await this.#node();
    const db = await this.#db();
    const existing = await db.read(db.dn(null, 'Root'), 'pki.root', pkiRoot);
    if (existing) {
      const m = await this.#maintain();
      return { fingerprint: existing.data.fingerprint, issuer: m.issuer ?? '', leafs: m.leafs };
    }
    if (await exists(this.#file('root.key')))
      throw new PlatformError('validation.invalid', {
        issues: 'a root CA key exists on this DC but no root CA in the directory; restore it or remove the key',
      });
    await this.#newKey(this.#file('root.key'));
    const csr = await this.#csr(this.#file('root.key'), `OpenDC Root CA ${n.domain}`);
    const cert = await this.#sign({
      csrPem: csr,
      ca: { selfKey: this.#file('root.key') },
      days: LIFETIME_DAYS.root,
      ext: extensionSection({ profile: 'root' }),
    });
    await writeFile(this.#file('root.pem'), cert, { mode: 0o644 });
    const x = new X509Certificate(cert);
    const root: PkiRoot = { certPem: cert, fingerprint: x.fingerprint256, holderNodeGuid: n.nodeGuid, holder: n.fqdn };
    await db.put(db.dn(null, 'Root'), 'pki.root', root, 'OpenDC root CA');
    await this.#pinRoot(cert);
    // this DC's issuing CA, signed right away
    await this.#newKey(this.#file('issuer.key'));
    const req = await this.#csr(this.#file('issuer.key'), `OpenDC Issuing CA ${n.host}`);
    await this.#publishIssuer(n.nodeGuid, n.host, req);
    const maint = await this.#maintain();
    return { fingerprint: x.fingerprint256, issuer: this.#issuerId(n.host), leafs: maint.leafs };
  }

  /** Pins the root: written once, never replaced from the directory. */
  async #pinRoot(certPem: string): Promise<void> {
    await mkdir(this.#p.trust, { recursive: true, mode: 0o755 });
    // the agent's umask would leave it 0700; the API reads the CA bundle here
    await chmod(this.#p.trust, 0o755);
    const pinned = join(this.#p.trust, 'root.pem');
    if (!(await exists(pinned))) await writeSystemFile(pinned, certPem, 0o644);
  }

  async #pinned(): Promise<X509Certificate | null> {
    return this.#readCert(join(this.#p.trust, 'root.pem'));
  }

  /** Signs an issuer CSR with the root key on this DC and publishes the issuing CA. */
  async #publishIssuer(nodeGuid: string, host: string, csrPem: string): Promise<PkiIssuer> {
    const db = await this.#db();
    const cert = await this.#sign({
      csrPem,
      ca: { cert: this.#file('root.pem'), key: this.#file('root.key') },
      days: LIFETIME_DAYS.issuer,
      ext: extensionSection({ profile: 'issuer' }),
    });
    const issuer: PkiIssuer = {
      id: this.#issuerId(host),
      nodeGuid,
      host,
      certPem: cert,
      crlPem: null,
      crlNumber: 0,
      crlNextUpdate: null,
      crlSerials: [],
    };
    await db.put(db.dn('Issuers', issuer.id), 'pki.issuer', issuer, `OpenDC issuing CA ${host}`);
    return issuer;
  }

  /** Root holder only: approves (signs) the pending issuer request of another DC. */
  approveIssuer(nodeGuid: string): Promise<OpResult<'ca.issuer.create'>> {
    return queued(() => this.#approveIssuer(nodeGuid));
  }

  async #approveIssuer(nodeGuid: string): Promise<OpResult<'ca.issuer.create'>> {
    if (!(await exists(this.#file('root.key'))))
      throw new PlatformError('validation.invalid', {
        issues: 'the root CA key is not on this DC; approve on the DC that holds it',
      });
    const db = await this.#db();
    const reqDn = db.dn('Requests', nodeGuid.toLowerCase());
    const req = await db.read(reqDn, 'pki.issuerRequest', pkiIssuerRequest);
    if (!req || req.data.state !== 'pending')
      throw new PlatformError('request.not-found', { what: `Pending issuer request of ${nodeGuid}` });
    // the requester must be a domain controller whose computer object has this GUID
    const n = await this.#node();
    const [dc] = await this.#samba.search(
      childDn(n.domainDn, 'OU', 'Domain Controllers'),
      'one',
      eq('objectGUID', guidToBytes(nodeGuid)),
      ['dNSHostName'],
    );
    if (!dc) throw new PlatformError('validation.invalid', { issues: `${nodeGuid} is not a domain controller` });
    const subject = await this.#tmp(async (dir) => {
      const f = join(dir, 'req.csr');
      await writeFile(f, req.data.csrPem, { mode: 0o600 });
      // verifies the CSR signature too
      return this.#ssl(['req', '-in', f, '-noout', '-verify', '-subject']);
    });
    if (
      !subject.includes(`CN = OpenDC Issuing CA ${req.data.host}`) &&
      !subject.includes(`CN=OpenDC Issuing CA ${req.data.host}`)
    )
      throw new PlatformError('validation.invalid', { issues: 'the request subject does not match the DC' });
    const issuer = await this.#publishIssuer(nodeGuid.toLowerCase(), req.data.host, req.data.csrPem);
    await db.put(reqDn, 'pki.issuerRequest', { ...req.data, state: 'signed' }, `Issuer request ${req.data.host}`);
    return { issuer: issuer.id, host: req.data.host };
  }

  // ---------------------------------------------------------------- maintenance

  /**
   * Idempotent: pins the root, gets this DC its issuing CA (request, or install once approved), issues or renews
   * the node, web and LDAPS certificates, and regenerates this issuer's CRL when revocations changed or it is due.
   */
  maintain(o: { renewFraction?: number } = {}): Promise<OpResult<'pki.maintain'>> {
    return queued(() => this.#maintain(o));
  }

  async #maintain(o: { renewFraction?: number } = {}): Promise<OpResult<'pki.maintain'>> {
    const n = await this.#node();
    const db = await this.#db();
    const root = await db.read(db.dn(null, 'Root'), 'pki.root', pkiRoot);
    if (!root) return { state: 'no-root', issuer: null, leafs: [], crl: false };
    await this.#pinRoot(root.data.certPem);
    const pinned = await this.#pinned();
    if (!pinned || pinned.fingerprint256 !== new X509Certificate(root.data.certPem).fingerprint256)
      throw new PlatformError('validation.invalid', {
        issues: 'the root CA in the directory is not the one this node trusts; refusing to use it',
      });
    // the issuing CA of this DC
    const id = this.#issuerId(n.host);
    const published = await db.read(db.dn('Issuers', id), 'pki.issuer', pkiIssuer);
    const issuerKey = this.#file('issuer.key');
    if (!(await exists(issuerKey))) await this.#newKey(issuerKey);
    const keyPub = await this.#ssl(['pkey', '-in', issuerKey, '-pubout']);
    const matches =
      published &&
      new X509Certificate(published.data.certPem).publicKey.export({ type: 'spki', format: 'pem' }) === keyPub;
    if (!matches) {
      const reqDn = db.dn('Requests', n.nodeGuid);
      const pending = await db.read(reqDn, 'pki.issuerRequest', pkiIssuerRequest);
      if (!pending || pending.data.state !== 'pending') {
        const csr = await this.#csr(issuerKey, `OpenDC Issuing CA ${n.host}`);
        const r: PkiIssuerRequest = {
          nodeGuid: n.nodeGuid,
          host: n.host,
          csrPem: csr,
          requestedAt: this.#now().toISOString(),
          state: 'pending',
        };
        await db.put(reqDn, 'pki.issuerRequest', r, `Issuer request ${n.host}`);
      }
      return { state: 'awaiting-approval', issuer: null, leafs: [], crl: false };
    }
    const issuerPem = published.data.certPem;
    await writeFile(this.#file('issuer.pem'), issuerPem, { mode: 0o644 });
    // the CA bundle: root + every issuing CA (for verifiers of node certificates and LDAPS)
    const issuers = await db.list('Issuers', 'pki.issuer', pkiIssuer);
    const bundle = [root.data.certPem, ...issuers.map((i) => i.certPem)].map((p) => p.trim()).join('\n') + '\n';
    await writeSystemFile(join(this.#p.trust, 'ca-bundle.pem'), bundle, 0o644);

    const leafs: LeafState[] = [];
    for (const profile of ['node', 'web', 'ldaps'] as const)
      leafs.push(await this.#leaf(profile, id, issuerPem, o.renewFraction));
    await this.#installServices(leafs, bundle);
    const crl = await this.#crl(published.data);
    return { state: 'ready', issuer: id, leafs, crl };
  }

  async #leaf(
    profile: 'node' | 'web' | 'ldaps',
    issuerId: string,
    issuerPem: string,
    fraction = 2 / 3,
  ): Promise<LeafState> {
    const n = await this.#node();
    const target =
      profile === 'web'
        ? { key: this.#p.consoleKey, cert: this.#p.consoleCert }
        : { key: this.#file(`${profile}.key`), cert: this.#file(`${profile}.pem`) };
    const cur = await this.#readCert(target.cert);
    const issuer = new X509Certificate(issuerPem);
    const fromThisIssuer = cur?.checkIssued(issuer) ?? false;
    // a certificate that doesn't belong to the key next to it (an interrupted run) is replaced too
    const keyMatches = cur ? await this.#keyMatches(target.key, cur) : false;
    // a revoked certificate of this node is replaced at once (peers refuse it already)
    const db0 = await this.#db();
    const revoked = cur
      ? (await db0.read(db0.dn('Certificates', cur.serialNumber), 'pki.cert', pkiCert))?.data.revoked
      : null;
    const due =
      !cur ||
      !fromThisIssuer ||
      !keyMatches ||
      !!revoked ||
      renewalDue(new Date(cur.validFrom), new Date(cur.validTo), this.#now(), fraction);
    if (!due)
      return { profile, serial: cur.serialNumber, notAfter: new Date(cur.validTo).toISOString(), renewed: false };

    const sans = leafSans({
      profile,
      fqdn: n.fqdn,
      ...(profile === 'node' ? { nodeGuid: n.nodeGuid } : {}),
      ...(profile === 'ldaps' ? { extraNames: [n.domain] } : {}),
    });
    const keyTmp = `${target.key}.${randomBytes(4).toString('hex')}.new`;
    await this.#newKey(keyTmp);
    const csr = await this.#csr(keyTmp, n.fqdn);
    const cert = await this.#sign({
      csrPem: csr,
      ca: { cert: this.#file('issuer.pem'), key: this.#file('issuer.key') },
      days: LIFETIME_DAYS[profile],
      ext: extensionSection({ profile, sans, crlUrl: `https://${n.fqdn}:8443/pki/crl/${issuerId}.crl` }),
    });
    const x = new X509Certificate(cert);
    // key and certificate (with the issuing CA, so peers can build the chain) replace the old pair
    await writeSystemFile(target.key, await readFile(keyTmp, 'utf8'), 0o600);
    await rm(keyTmp, { force: true });
    await writeSystemFile(target.cert, `${cert.trim()}\n${issuerPem.trim()}\n`, 0o644);
    const db = await this.#db();
    const entry: PkiCert = {
      serial: x.serialNumber,
      issuerId,
      profile,
      subject: n.fqdn,
      sans,
      nodeGuid: profile === 'node' ? n.nodeGuid : null,
      notBefore: new Date(x.validFrom).toISOString(),
      notAfter: new Date(x.validTo).toISOString(),
      revoked: null,
    };
    await db.put(db.dn('Certificates', x.serialNumber), 'pki.cert', entry, `${profile} ${n.fqdn}`);
    return { profile, serial: x.serialNumber, notAfter: entry.notAfter, renewed: true };
  }

  /** Samba LDAPS on the issued certificate; the services' LDAP CA bundle; restarts what changed. */
  async #installServices(leafs: LeafState[], bundle: string): Promise<void> {
    const renewed = new Set(leafs.filter((l) => l.renewed).map((l) => l.profile));
    // the API and watcher verify LDAPS against ldap-ca: the OpenDC CAs plus Samba's own (until LDAPS switched)
    const sambaCa = await readFile(join(this.#samba.paths.tlsDir, 'ca.pem'), 'utf8').catch(() => null);
    const ldapCaChanged = await writeSystemFile(this.#p.ldapCa, ldapCaBundle(bundle, sambaCa), 0o600);
    const conf = this.#samba.paths.smbConf;
    const text = await readFile(conf, 'utf8');
    let next = withGlobalParam(text, 'tls enabled', 'yes');
    next = withGlobalParam(next, 'tls keyfile', this.#file('ldaps.key'));
    next = withGlobalParam(next, 'tls certfile', this.#file('ldaps.pem'));
    next = withGlobalParam(next, 'tls cafile', join(this.#p.trust, 'ca-bundle.pem'));
    const smbChanged = next !== text;
    if (smbChanged) await writeSystemFile(conf, next, 0o644);
    if (smbChanged || renewed.has('ldaps')) await this.#os.services.restart('samba-ad-dc');
    if (renewed.has('web') || renewed.has('node') || ldapCaChanged) await this.#os.services.restart('opendc-api');
    if (ldapCaChanged) await this.#os.services.restart('opendc-watcher').catch(() => undefined);
  }

  /** This issuer's CRL: regenerated when its revocations changed or it expires within two days. */
  async #crl(issuer: PkiIssuer): Promise<boolean> {
    const db = await this.#db();
    const revoked = (await db.list('Certificates', 'pki.cert', pkiCert)).filter(
      (c) => c.issuerId === issuer.id && c.revoked,
    );
    const serials = revoked.map((c) => c.serial).sort();
    const nextUpdate = issuer.crlNextUpdate ? new Date(issuer.crlNextUpdate) : null;
    const fresh = nextUpdate && nextUpdate.getTime() - this.#now().getTime() > 2 * 86_400_000;
    if (issuer.crlPem && fresh && serials.join(',') === [...issuer.crlSerials].sort().join(',')) return false;
    const crlPem = await this.#tmp(async (dir) => {
      const index = revoked
        .map(
          (c) =>
            `R\t${utc(new Date(c.notAfter))}\t${utc(new Date(c.revoked?.at ?? this.#now()))},${c.revoked?.reason ?? 'unspecified'}\t${c.serial}\tunknown\t/CN=${safeCn(c.subject)}\n`,
        )
        .join('');
      await writeFile(join(dir, 'index.txt'), index, { mode: 0o600 });
      await writeFile(join(dir, 'crlnumber'), (issuer.crlNumber + 1).toString(16).padStart(2, '0') + '\n', {
        mode: 0o600,
      });
      const cfg = [
        '[ca]',
        'default_ca = CA',
        '[CA]',
        `database = ${join(dir, 'index.txt')}`,
        `crlnumber = ${join(dir, 'crlnumber')}`,
        'default_md = sha256',
        'default_crl_days = 7',
        'crl_extensions = crl_ext',
        '[crl_ext]',
        'authorityKeyIdentifier = keyid:always',
        '',
      ].join('\n');
      await writeFile(join(dir, 'ca.cnf'), cfg, { mode: 0o600 });
      const out = join(dir, 'crl.pem');
      await this.#ssl([
        'ca',
        '-gencrl',
        '-batch',
        '-config',
        join(dir, 'ca.cnf'),
        '-cert',
        this.#file('issuer.pem'),
        '-keyfile',
        this.#file('issuer.key'),
        '-out',
        out,
      ]);
      return readFile(out, 'utf8');
    });
    await db.put(
      db.dn('Issuers', issuer.id),
      'pki.issuer',
      {
        ...issuer,
        crlPem,
        crlNumber: issuer.crlNumber + 1,
        crlNextUpdate: new Date(this.#now().getTime() + 7 * 86_400_000).toISOString(),
        crlSerials: serials,
      },
      `OpenDC issuing CA ${issuer.host}`,
    );
    return true;
  }

  /** Records a revocation in the index; this DC regenerates its own issuer's CRL at once. */
  revoke(serial: string, reason: string): Promise<OpResult<'cert.revoke'>> {
    return queued(() => this.#revoke(serial, reason));
  }

  async #revoke(serial: string, reason: string): Promise<OpResult<'cert.revoke'>> {
    const db = await this.#db();
    const dn = db.dn('Certificates', serial.toUpperCase());
    const cur = await db.read(dn, 'pki.cert', pkiCert);
    if (!cur) throw new PlatformError('request.not-found', { what: `Certificate ${serial}` });
    if (!cur.data.revoked)
      await db.put(
        dn,
        'pki.cert',
        { ...cur.data, revoked: { at: this.#now().toISOString(), reason } },
        `${cur.data.profile} ${cur.data.subject} (revoked)`,
      );
    const n = await this.#node();
    let crl = false;
    if (cur.data.issuerId === this.#issuerId(n.host)) {
      const issuer = await db.read(db.dn('Issuers', cur.data.issuerId), 'pki.issuer', pkiIssuer);
      if (issuer) crl = await this.#crl(issuer.data);
    }
    return { serial: cur.data.serial, issuerId: cur.data.issuerId, crlUpdated: crl };
  }
}
